/* Reset & base */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #f0f4f8;
  background-image: radial-gradient(circle at 20% 30%, #d0e0f0 0%, #f0f4f8 70%);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: #ffffff;
  border-radius: 24px;
  padding: 32px 24px;
  max-width: 440px;
  width: 100%;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.1);
  text-align: center;
}

h1 {
  font-size: 2rem;
  font-weight: 700;
  color: #1e293b;
  margin-bottom: 8px;
  letter-spacing: -0.02em;
}

.subtitle {
  font-size: 1rem;
  color: #475569;
  margin-bottom: 24px;
  line-height: 1.5;
}

.status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
  min-height: 32px;
}

.swap-counter {
  font-size: 1.125rem;
  font-weight: 600;
  color: #334155;
}

.solved {
  font-size: 1.125rem;
  font-weight: 700;
  color: #16a34a;
  background: #dcfce7;
  padding: 4px 12px;
  border-radius: 999px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-bottom: 24px;
  aspect-ratio: 1 / 1;
  max-width: 360px;
  margin-left: auto;
  margin-right: auto;
}

.tile {
  border-radius: 12px;
  border: 3px solid transparent;
  cursor: pointer;
  transition: border-color 0.15s, transform 0.1s;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0;
  padding: 0;
  min-width: 0;
  aspect-ratio: 1 / 1;
}

.tile:hover {
  transform: scale(1.05);
}

.tile:focus-visible {
  outline: 3px solid #1e293b;
  outline-offset: 2px;
}

.tile.selected {
  border-color: #1e293b;
  box-shadow: 0 0 0 2px #ffffff inset;
}

.tile:active {
  transform: scale(0.95);
}

/* Color classes */
.tile.red { background-color: #ef4444; }
.tile.blue { background-color: #3b82f6; }
.tile.green { background-color: #22c55e; }
.tile.yellow { background-color: #eab308; }

.button {
  font-family: inherit;
  font-size: 1.125rem;
  font-weight: 600;
  padding: 12px 32px;
  border: none;
  border-radius: 999px;
  background: #1e293b;
  color: #ffffff;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  min-width: 140px;
}

.button:hover {
  background: #0f172a;
}

.button:focus-visible {
  outline: 3px solid #1e293b;
  outline-offset: 3px;
}

.button:active {
  transform: scale(0.97);
}

/* Responsive */
@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.75rem;
  }
  .grid {
    gap: 6px;
  }
}

(function() {
  'use strict';

  const COLORS = ['red', 'blue', 'green', 'yellow'];
  const GRID_SIZE = 4;
  const TOTAL_TILES = GRID_SIZE * GRID_SIZE;

  const gridEl = document.getElementById('grid');
  const swapCountEl = document.getElementById('swapCount');
  const solvedMessageEl = document.getElementById('solvedMessage');
  const shuffleBtn = document.getElementById('shuffleBtn');

  let tiles = [];
  let swapCount = 0;
  let selectedIndex = null;

  /**
   * Create a solved board: each row is a single color.
   * Row 0 = red, row 1 = blue, row 2 = green, row 3 = yellow.
   */
  function createSolvedBoard() {
    const board = [];
    for (let row = 0; row < GRID_SIZE; row++) {
      for (let col = 0; col < GRID_SIZE; col++) {
        board.push(COLORS[row]);
      }
    }
    return board;
  }

  /**
   * Shuffle the board using Fisher-Yates.
   * Ensure the result is not already solved.
   */
  function shuffleBoard(board) {
    const arr = board.slice();
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    // If accidentally solved, shuffle again (rare but possible)
    if (isSolved(arr)) {
      return shuffleBoard(arr);
    }
    return arr;
  }

  /**
   * Check if every row has a single color.
   */
  function isSolved(board) {
    for (let row = 0; row < GRID_SIZE; row++) {
      const start = row * GRID_SIZE;
      const rowColor = board[start];
      for (let col = 1; col < GRID_SIZE; col++) {
        if (board[start + col] !== rowColor) {
          return false;
        }
      }
    }
    return true;
  }

  /**
   * Check if two indices are adjacent (share an edge).
   */
  function areAdjacent(i, j) {
    const rowI = Math.floor(i / GRID_SIZE);
    const colI = i % GRID_SIZE;
    const rowJ = Math.floor(j / GRID_SIZE);
    const colJ = j % GRID_SIZE;
    return Math.abs(rowI - rowJ) + Math.abs(colI - colJ) === 1;
  }

  /**
   * Swap two tiles in the board array.
   */
  function swapTiles(i, j) {
    [tiles[i], tiles[j]] = [tiles[j], tiles[i]];
    swapCount++;
    updateUI();
  }

  /**
   * Handle tile click.
   */
  function onTileClick(index) {
    if (selectedIndex === null) {
      // First selection
      selectedIndex = index;
      updateSelection();
    } else if (selectedIndex === index) {
      // Deselect
      selectedIndex = null;
      updateSelection();
    } else if (areAdjacent(selectedIndex, index)) {
      // Swap
      swapTiles(selectedIndex, index);
      selectedIndex = null;
      updateSelection();
    } else {
      // Not adjacent: change selection
      selectedIndex = index;
      updateSelection();
    }
  }

  /**
   * Update the visual selection state.
   */
  function updateSelection() {
    const tileEls = gridEl.children;
    for (let i = 0; i < tileEls.length; i++) {
      tileEls[i].classList.toggle('selected', i === selectedIndex);
      tileEls[i].setAttribute('aria-selected', i === selectedIndex ? 'true' : 'false');
    }
  }

  /**
   * Render the grid from the tiles array.
   */
  function renderGrid() {
    gridEl.innerHTML = '';
    for (let i = 0; i < TOTAL_TILES; i++) {
      const tile = document.createElement('button');
      tile.className = 'tile ' + tiles[i];
      tile.setAttribute('role', 'gridcell');
      tile.setAttribute('aria-label', 'Tile ' + (i + 1) + ': ' + tiles[i]);
      tile.dataset.index = i;
      tile.addEventListener('click', function() {
        onTileClick(i);
      });
      gridEl.appendChild(tile);
    }
  }

  /**
   * Update the entire UI: colors, swap count, solved message.
   */
  function updateUI() {
    // Update tile colors
    const tileEls = gridEl.children;
    for (let i = 0; i < tileEls.length; i++) {
      tileEls[i].className = 'tile ' + tiles[i];
      tileEls[i].setAttribute('aria-label', 'Tile ' + (i + 1) + ': ' + tiles[i]);
    }
    // Update swap count
    swapCountEl.textContent = 'Swaps: ' + swapCount;
    // Update solved message
    if (isSolved(tiles)) {
      solvedMessageEl.hidden = false;
    } else {
      solvedMessageEl.hidden = true;
    }
  }

  /**
   * Start a new puzzle.
   */
  function newPuzzle() {
    tiles = shuffleBoard(createSolvedBoard());
    swapCount = 0;
    selectedIndex = null;
    renderGrid();
    updateUI();
    updateSelection();
  }

  // Event listener for shuffle button
  shuffleBtn.addEventListener('click', newPuzzle);

  // Initialize
  newPuzzle();
})();
